        h,
      );
      break;
  }

  return {
    title: shellTitle,
    body: shellView(
      shellTitle,
      organizationAdmin,
      [screenContent],
      {
        value: locale,
        busy: model.languageBusy,
        failure: Option.getOrUndefined(model.languageFailure),
        onChange: (value) => Message.LanguageChanged({ value }),
      },
      h,
      model.route._tag === "RoundResults",
    ),
  };
